# Optional helper: regenerates the HTML pages. Plain static HTML works without running it.
def page(f,title,desc,body,js="",bodycls=""):
    open(f,"w").write(f'''<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><meta name="description" content="{desc}">
<meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website">
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500&family=Lora:wght@400;500&display=swap" rel="stylesheet">
<script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="css/styles.css"></head>
<body><a href="#main" class="sr-only focus:not-sr-only p-3">Skip to content</a><div id="site-header"></div>
<main id="main">{body}</main><div id="site-footer"></div>
<script src="js/main.js"></script>{js}</body></html>''')
CTA='<div id="site-cta"></div>'
def hero(eb,h,p,extra=""):
    return f'<section class="iv sec"><div class="wrap"><p class="eyebrow">{eb}</p><h1 class="serif h1 max-w-3xl">{h}</h1><p class="mut mt-6 max-w-xl">{p}</p>{extra}</div></section>'
A='<span class="ar">↗</span>'
BTN=lambda t,h,c="btn-p":f'<a class="btn {c}" href="{h}">{t} {A}</a>'
def three(items,cls="iv"):
    return '<div class="grid md:grid-cols-3 gap-8">'+"".join(f'<div class="border-t border-[var(--line)] pt-4 rv"><h3 class="serif h3">{a}</h3><p class="mut mt-3">{b}</p></div>' for a,b in items)+'</div>'
ph=lambda c="aspect-[4/5]",cap="Placeholder image — replace with approved imagery (assets/images)":f'<figure><div class="ph {c}" role="img" aria-label="Placeholder editorial image"></div><figcaption class="text-xs text-[var(--mut)] mt-3">{cap}</figcaption></figure>'

# HOME
home=f'''<section class="iv pt-16 pb-10"><div class="wrap grid md:grid-cols-2 gap-12 items-center"><div>
<p class="eyebrow">Independent perspective. Considered action.</p><h1 class="serif h1">Clarity for the decisions that matter.</h1>
<p class="mut mt-6 max-w-md">David Benson — CEO &amp; Consultant. Bringing a thoughtful, multidisciplinary perspective to business, leadership and life.</p>
<div class="flex flex-wrap gap-3 mt-8">{BTN("Book a consultation","contact.html?subject=Consultation")}{BTN("Explore resources","resources.html","")}</div>
<p class="text-xs text-[var(--mut)] mt-6">A space for better questions. A path to practical next steps.</p></div>
<div>{ph("aspect-[4/3]","Perspective begins with space to think. · DB / 2026")}</div></div>
<div class="wrap mt-10 pt-5 border-t border-[var(--line)] grid md:grid-cols-3 gap-2 text-xs text-[var(--mut)]"><span>01 Business &amp; economics</span><span class="md:text-center">02 People &amp; leadership</span><span class="md:text-right">03 Purpose &amp; perspective</span></div></section>
<section class="sec"><div class="wrap grid md:grid-cols-2 gap-12 rv"><div><p class="eyebrow">About David Benson</p><h2 class="serif h2">A wider lens. A more grounded way forward.</h2></div>
<div><p class="mut">Complex questions rarely belong to just one discipline. This consulting practice brings business thinking into conversation with human behaviour, leadership and personal values.</p>
<p class="mut mt-4">The approach is simple: listen carefully, examine assumptions and translate insight into decisions you can act on.</p>
<a class="inline-block mt-5 text-[13px] text-[var(--brn)]" href="portfolio.html">Meet David &amp; explore his profile {A}</a>
<p class="text-xs text-[var(--mut)] mt-4">Illustrative profile copy — biography to be confirmed before publishing.</p></div></div></section>
<section class="iv sec"><div class="wrap"><p class="eyebrow">The principles behind the practice</p><div class="grid md:grid-cols-2 gap-6">
<div class="card rv"><p class="eyebrow">Vision</p><h2 class="serif h2">More thoughtful decisions. More meaningful progress.</h2><p class="mut mt-4">A world where individuals and organisations move forward with clearer thinking, stronger purpose and awareness of their wider impact.</p></div>
<div class="card rv"><p class="eyebrow">Mission</p><h2 class="serif h2">Make insight useful in the real world.</h2><p class="mut mt-4">To connect perspectives, ask better questions and turn complex challenges into considered, practical directions.</p></div></div></div></section>
<section class="sec"><div class="wrap"><div class="md:flex justify-between items-end mb-10"><div><p class="eyebrow">Seven connected perspectives</p><h2 class="serif h2">Expertise without silos.</h2><p class="mut mt-3">Explore the areas where a fresh perspective can move your thinking forward.</p></div>{BTN("View all services","services.html","mt-4")}</div>
<div data-services="rows"></div>
<div class="iv rounded-md p-8 mt-10 md:flex justify-between items-center gap-6"><div><p class="eyebrow">Not sure where to begin?</p><h3 class="serif h2">Start with the question, not the category.</h3><p class="mut mt-3">Many challenges sit between disciplines. A first conversation can help identify the right focus.</p></div>{BTN("Let's find your focus","contact.html?area=General%20enquiry","mt-6 shrink-0")}</div></div></section>
<section class="dk sec"><div class="wrap"><p class="eyebrow">How we work together</p><h2 class="serif h2 mb-10">Space to think. Structure to act.</h2><div class="grid md:grid-cols-3 gap-8">
{"".join(f'<div class="border-t border-white/20 pt-4 rv"><p class="text-xs tracking-widest text-[#c9b8a4]">{a}</p><p class="mut mt-3">{b}</p></div>' for a,b in [("01 / UNDERSTAND","Begin with your context, priorities and the questions behind the challenge."),("02 / EXPLORE","Examine options, connect perspectives and test the assumptions that matter."),("03 / MOVE FORWARD","Define a practical direction, with clear actions and room for reflection.")])}</div></div></section>
<section class="sec"><div class="wrap grid md:grid-cols-2 gap-12 items-center"><div class="iv rounded-md p-8 rv"><p class="eyebrow">Professional profile</p><blockquote class="serif h2">“Good advice begins with understanding what matters to you.”</blockquote><p class="text-xs text-[var(--brn)] mt-4">A guiding principle of the practice</p></div>
<div><p class="eyebrow">Behind the perspective</p><h2 class="serif h2">Get to know the thinking behind the work.</h2><p class="mut mt-4">Explore David's professional profile, approach and the areas of practice that connect his work.</p><p class="text-xs text-[var(--mut)] mt-3">Qualifications, experience and achievements are marked for verification, not presented as established claims.</p><div class="mt-6">{BTN("Explore portfolio","portfolio.html","")}</div></div></div></section>
<section class="wrap pb-24"><div class="border-t border-[var(--line)] pt-12 md:flex justify-between items-end mb-10"><div><p class="eyebrow">The perspective library</p><h2 class="serif h2">Ideas to return to.</h2><p class="mut mt-3">Books, articles and practical tools for thinking more clearly.</p></div>{BTN("Browse all resources","resources.html","mt-4")}</div>
<div id="featured" class="grid md:grid-cols-3 gap-6"></div><p class="text-xs text-[var(--mut)] mt-8">Conceptual catalogue · Sample titles and pricing · Digital PDF editions</p></section>{CTA}'''
page("index.html","Life Consultancy — Clarity for the decisions that matter","Independent consulting across business, people and perspective. Book a consultation or explore the perspective library.",home,'<script src="js/resources.js"></script>')

# SERVICES
sv=hero("Consulting services","Different disciplines. A connected perspective.","Thoughtful support for business challenges, human questions and personal direction. Begin with what matters to you; we'll shape the focus together.")+f'''
<section class="sec"><div class="wrap"><div class="md:grid grid-cols-2 gap-12 mb-10"><p class="eyebrow">Explore the practice</p><p class="mut">Each area can stand alone or connect with others. These are discussion-led services, tailored around your context rather than a one-size-fits-all programme.</p></div><div data-services="full"></div></div></section>
<section class="iv sec"><div class="wrap grid md:grid-cols-2 gap-10 items-center"><div><p class="eyebrow">Connected challenges</p><h2 class="serif h2">We don't have to start with a label.</h2></div><div><p class="mut">If your question spans several disciplines, we can begin by mapping the context and deciding where a conversation will be most useful.</p><div class="mt-6">{BTN("Find the right focus","contact.html?area=General%20enquiry")}</div></div></div></section>
<section class="sec"><div class="wrap"><p class="eyebrow">Your first conversation</p><h2 class="serif h2 mb-10">A useful starting point, not a sales pitch.</h2>{three([("Share your context","Tell us what you're navigating and what you hope to understand or change."),("Agree the focus","Discuss the scope, format and suitability of an engagement before committing."),("Define next steps","Identify what a useful outcome could look like and how to work towards it.")])}
<p class="text-xs text-[var(--mut)] mt-10">Consulting offers general strategic and reflective guidance. It does not replace regulated financial advice, clinical care or legal counsel.</p></div></section>{CTA}'''
page("services.html","Services — Life Consultancy","Seven connected consulting perspectives: finance, psychology, leadership, governance, life philosophy, product marketing and politics.",sv)

# PORTFOLIO
pf=f'''<section class="iv sec"><div class="wrap grid md:grid-cols-2 gap-12 items-center"><div><p class="eyebrow">Portfolio / Professional profile</p><h1 class="serif h1">David Benson.</h1><p class="serif text-2xl text-[var(--brn)] mt-3">CEO &amp; Consultant</p><p class="mut mt-5">A thoughtful perspective at the intersection of business, people and purpose.</p><div class="flex flex-wrap gap-3 mt-8">{BTN("Work with David","contact.html?subject=Consultation")}{BTN("Explore services","services.html","")}</div></div>{ph("aspect-[4/3]","Editorial workspace imagery; no authentic portrait has been supplied.")}</div></section>
<section class="sec"><div class="wrap grid md:grid-cols-2 gap-12"><div><p class="eyebrow">Biography</p><h2 class="serif h2">Curiosity as a starting point. Clarity as a direction.</h2></div><div><p class="mut">David's proposed professional profile centres on a multidisciplinary consulting approach: considering the economic, organisational and human dimensions of a question together.</p><p class="mut mt-4">The practice is designed to create space for reflection while keeping the conversation grounded in real choices. The aim is not to provide a ready-made answer, but to help define a more useful question and a considered next step.</p><p class="text-xs text-[var(--mut)] mt-4">Illustrative biography — replace with David's approved personal history and professional background before publishing.</p></div></div></section>
<section class="iv sec"><div class="wrap"><p class="eyebrow">Practice at a glance</p><div class="grid md:grid-cols-3 gap-6">{"".join(f'<div class="card"><h3 class="serif h2">{a}</h3><p class="mut mt-3">{b}</p></div>' for a,b in [("Business","Finance, economics, product marketing, management and governance."),("People","Human psychology, leadership and the dynamics of working together."),("Perspective","Life philosophy, politics and the context behind consequential decisions.")])}</div></div></section>
<section class="sec"><div class="wrap grid md:grid-cols-2 gap-12">{"".join(f'<div><p class="eyebrow">{e}</p><h2 class="serif h2 pb-5 border-b border-[var(--line)]">{h}</h2>'+"".join(f'<div class="py-6 border-b border-[var(--line)]"><h3 class="serif h3">{a}</h3><p class="mut mt-2">{b}</p><p class="text-[10.5px] tracking-wider text-[var(--brn)] mt-3">PLACEHOLDER — {c}</p></div>' for a,b,c in rows)+'</div>' for e,h,rows in [("Qualifications","A profile built on verified foundations.",[("Education &amp; professional development","Add confirmed academic qualifications, relevant training and professional development here.","degrees, institutions and dates to be supplied."),("Memberships &amp; accreditations","Include only current professional memberships or accreditations that can be independently verified.","no memberships or credentials claimed.")]),("Experience","The context behind the practice.",[("Executive responsibilities","Add David's confirmed organisation, executive remit and relevant responsibilities.","organisation, role history and dates to be supplied."),("Consulting engagements","Describe approved examples of advisory work, including context, approach and lessons learned.","engagement details and permissions to be supplied.")])])}</div></section>
<section class="iv sec"><div class="wrap"><p class="eyebrow">Achievements &amp; selected work</p><h2 class="serif h2">Evidence deserves the same care as advice.</h2><p class="mut mt-4 mb-8">There are no verified achievements or client case studies in this concept. The following spaces show how approved work can be presented without overstating results.</p><div class="grid md:grid-cols-3 gap-6">{"".join(f'<div class="card"><p class="eyebrow">To be confirmed</p><h3 class="serif h2">{a}</h3><p class="mut mt-3">{b}</p></div>' for a,b in [("Selected engagement","Add an approved challenge, the contribution made and a verified outcome."),("Published contribution","Add a confirmed publication, speaking contribution or original piece of research."),("Professional milestone","Add a documented milestone and the context that makes it relevant.")])}</div></div></section>{CTA}'''
page("portfolio.html","Portfolio — Life Consultancy","Professional profile of David Benson, CEO & Consultant. Biography, qualifications and experience (placeholders to be confirmed).",pf)

# RESOURCES
rs=hero("E-Resources / The perspective library","A little perspective. A lasting reference.","Explore books, articles and practical projects created to support clearer thinking. Digital resources to read, reflect on and put to use at your own pace.")+f'''
<section class="sec"><div class="wrap"><div class="flex flex-col md:flex-row gap-3"><div class="flex-1"><label for="q" class="sr-only">Search resources</label><input id="q" type="search" placeholder="Search books, articles and projects"></div>
<button id="cart-toggle" class="btn" aria-controls="cart-panel">Your cart <span data-count>0 items</span></button></div>
<div id="cart-panel" class="card mt-3" hidden><ul id="cart-list" aria-live="polite"></ul></div>
<div class="flex flex-wrap gap-2 mt-5 pb-5 border-b border-[var(--line)]" role="group" aria-label="Filter by category">{"".join(f'<button class="chip" data-cat="{v}" aria-pressed="{str(v=="All").lower()}">{t}</button>' for v,t in [("All","All resources"),("Books","Books"),("Articles","Articles"),("Projects","Projects")])}</div>
<p id="shown" class="text-xs text-[var(--mut)] my-5" aria-live="polite"></p><div id="grid" class="grid md:grid-cols-2 lg:grid-cols-3 gap-6"></div>
<p class="text-xs text-[var(--mut)] mt-8">Conceptual catalogue — sample titles, covers and prices. Product content, licensing and delivery terms must be confirmed before publishing. Prices shown in USD.</p></div></section>
<section class="iv sec"><div class="wrap"><p class="eyebrow">Digital by design</p><h2 class="serif h2 mb-8">Useful ideas. No shipping required.</h2>{three([("Read your way","PDF editions intended for reading on a laptop, tablet or phone."),("Reflect &amp; apply","Books for perspective, articles for a focused read and projects for practical exploration."),("Keep a reference","Personal-use digital resources you can return to as your questions evolve.")])}<p class="text-xs text-[var(--mut)] mt-8">This design shows a proposed digital marketplace. Downloads and purchasing are not enabled in this static concept.</p></div></section>{CTA}'''
page("resources.html","E-Resources — Life Consultancy","The Perspective Library: digital books, articles and projects for clearer thinking.",rs,'<script src="js/resources.js"></script>')
page("resource-detail.html","Resource — Life Consultancy","Digital resource from The Perspective Library by David Benson.",'<div id="detail"></div>','<script src="js/resources.js"></script>')

# CONTACT
opts="".join(f"<option>{o}</option>" for o in ["Finance & Economics","Human Psychology","Leadership","Management & Governance","Life Philosophy","Product Marketing","Politics","General enquiry"])
fld=lambda n,l,t="text",ph="",req=True:f'<div><label for="{n}">{l}{" *" if req else " (optional)"}</label><input id="{n}" name="{n}" type="{t}" placeholder="{ph}" {"required" if req else ""} autocomplete="off"><p class="err" id="e-{n}" role="alert"></p></div>'
ct=hero("Contact / Begin a conversation","What are you thinking through?","A decision, a new direction or a question that needs a fresh perspective. Share a little context and the kind of support you're looking for.")+f'''
<section class="sec"><div class="wrap grid md:grid-cols-12 gap-12"><div class="md:col-span-7"><h2 class="serif h2">Tell us a little more.</h2><p class="text-xs text-[var(--mut)] mt-2 mb-6">Fields marked * are required. Please don't include sensitive financial or personal information.</p>
<form id="cf" novalidate class="space-y-5"><div class="grid sm:grid-cols-2 gap-5">{fld("name","Full name",ph="Your full name")}{fld("email","Email address","email","you@example.com")}</div>
<div class="grid sm:grid-cols-2 gap-5">{fld("organisation","Organisation",ph="Organisation or independent",req=False)}{fld("phone","Phone","tel","Include country code",False)}</div>
<div><label for="area">Area of interest *</label><select id="area" name="area"><option value="">Select a service or general enquiry</option>{opts}</select><p class="err" id="e-area" role="alert"></p></div>
{fld("subject","Subject",ph="What would you like to discuss?")}
<div><label for="message">Your message *</label><textarea id="message" name="message" rows="6" placeholder="Tell us about your context, priorities and what a useful outcome would look like…"></textarea><p class="err" id="e-message" role="alert"></p></div>
<div><label class="flex gap-3 items-start font-normal"><input id="agree" name="agree" type="checkbox" class="!w-5 mt-0.5"><span>I agree that my details may be used to respond to this enquiry. I have read the <a class="underline" href="#">Privacy policy</a>. *</span></label><p class="err" id="e-agree" role="alert"></p></div>
<button class="btn btn-p" type="submit">Send message {A}</button><p id="ok" tabindex="-1" hidden class="text-sm text-[var(--brn)]">Thanks — this concept form does not send email yet. Connect a form service before publishing.</p></form></div>
<aside class="md:col-span-5"><div class="iv rounded-md p-8"><p class="eyebrow">Business details</p><h3 class="serif h2 pb-5 border-b border-[var(--line)]">David Benson CEO &amp; Consultant</h3>{"".join(f'<p class="eyebrow mt-5 mb-1">{a}</p><p class="text-sm">{b}</p>' for a,b in [("Email","hello@davidbenson.example"),("Phone","+1 (202) 555-0142"),("Location","Business location to be confirmed"),("Consultation format","Online or in person to be confirmed"),("Availability","Hours and time zone to be confirmed")])}<p class="text-xs text-[var(--mut)] mt-6 pt-4 border-t border-[var(--line)]">Sample contact details — replace email, phone, location, format and availability before publishing.</p></div></aside></div></section>
<section class="iv sec"><div class="wrap"><p class="eyebrow">What happens next</p>{three([("Your context comes first.","The conversation starts by understanding your question and the support you're seeking."),("Scope before commitment.","Any proposed engagement should clarify focus, format and terms before you decide."),("A considered next step.","If another type of support is more appropriate, that belongs in the conversation too.")])}</div></section>'''
page("contact.html","Contact — Life Consultancy","Begin a conversation with David Benson. Share your context and the kind of support you're looking for.",ct,'<script src="js/contact.js"></script>')
